+struct less_than_ptr
+{
+    bool operator()(gsMesh<>::gsVertexHandle lhs, gsMesh<>::gsVertexHandle rhs)
+    {
+        return ((*lhs) < (*rhs));
+    }
+};
+
+struct equal_ptr
+{
+    bool operator()(gsMesh<>::gsVertexHandle lhs, gsMesh<>::gsVertexHandle rhs)
+    {
+        return ((*lhs) == (*rhs));
+    }
+};
