            "Writes points to Paraview");
    m.def("gsWriteParaviewPoints",
            static_cast<void (*)(const gsMatrix<real_t> &, const gsMatrix<real_t> &, const gsMatrix<real_t> &, const gsMatrix<real_t> &,std::string const &)>(&gsWriteParaviewPoints),
            "Writes points to Paraview");

}

